def round_half_to_even(n):
    n_frac, n_int = math.modf(n)
    if n_frac > 0.5 or n_frac == 0.5 and (n_int % 2 != 0):
        return int(n) + 1
    else:
        return int(n)

def round_half_to_even(n):
    if n == math.floor(n):
        return n
    else:
        fractional, integer = math.modf(n)
        if fractional > 0.5:
            return math.ceil(n)
        else:
            return math.floor(n)

