def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception.

    Arguments:
        e (Exception): Any exception instance.
        max_level (int): Maximum call stack level (default 30)
        max_path_level (int): Maximum path level (default 5)

    Returns:
        str: The exception's readable string.
    """

    if not isinstance(e, Exception):
        raise ValueError("Parameter e is not an instance of Exception")

    traceback_list = []
    for tb_entry in e.__traceback__.extract(limit=max_level):
        if tb_entry.filename == "<ipython-input-<>":
            break

        traceback_list.append(f"File {tb_entry.filename}, line {tb_entry.lineno}, in {tb_entry.name}")

    traceback_string = "\n".join(traceback_list)
    if max_path_level > 0:
        for i in range(max_path_level):
            path = ".".join(traceback_string.split(".")[:-i])
            if path not in MODULES_TO_HIDE:
                break

        return f"{path}: {traceback_string}"
    else:
        return traceback_string

