def format(self, sql, params):
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    Arguments:
        sql (str or bytes): The SQL query.
        params (Mapping or Sequence): Contains the set of in-style parameters.
            If .SQLParams.in_style is a named parameter style, then params
            must be a Mapping.
            If .SQLParams.in_style is an ordinal parameter style, then params
            must be a Sequence.

    Returns:
        tuple (str or bytes, dict or list): The formatted SQL query, and the
        set of converted out-style parameters.
    """
    result = []

    if isinstance(params, dict):
        for index, param in enumerate(params.items()):
            if index > 0:
                result.append(self.separator)

            key, value = param

            if isinstance(key, int):
                result.append(f'${index + 1}')
            else:
                result.append(f':{key}')

            if isinstance(value, str):
                result.append(f"'{value}'")
            else:
                result.append(f'{value}')
    elif isinstance(params, list):
        for index, value in enumerate(params):
            if index > 0:
                result.append(self.separator)

            if isinstance(value, str):
                result.append(f"'{value}'")
            else:
                result.append(f'{value}')
    else:
        raise ValueError(f'Expected params to be a Mapping or Sequence, got {type(params)}')

    return ''.join(result), params

def format(self, sql, params):
    if isinstance(params, Mapping):
        # Convert named parameters
        out_params = {}
        for name, value in params.items():
            out_params[name] = str(value)
        return (sql % out_params, out_params)
    elif isinstance(params, Sequence):
        # Convert ordinal parameters
        out_params = []
        for value in params:
            out_params.append(str(value))
        return (sql % tuple(out_params), out_params)
    else:
        raise TypeError("params must be a Mapping or a Sequence")

