        # Check if path is a directory
        if not os.path.isdir(path):
            raise ValueError(f"Path is not a directory: {path}")

        # Check if path is a pyfs root
        if not os.path.isfile(os.path.join(path, "pyfs.json")):
            raise ValueError(f"Path is not a pyfs root: {path}")

        # Load root files
        root_files = load_root_files(path)

        # Check if all required files are present
        for req in OCFL_OBJECT_REQUIRES:
            if req not in root_files:
                raise ValueError(f"Required file not found: {req}")

        # Check if all header files are present
        for head in OCFL_OBJECT_HEADERS:
            if head not in root_files:
                raise ValueError(f"Header file not found: {head}")

        # Check file sizes
        dir_map = {}
        for file in os.listdir(path):
            file_path = os.path.join(path, file)
            if os.path.isfile(file_path) and file.lower() not in OCFL_OBJECT_HEADERS:
                file_size = os.path.getsize(file_path)
                file_width = os.stat(file_path).st_size
                if file_size != file_width:
                    raise ValueError(f"File size mismatch: {file} - expected: {file_size}, actual: {file_width}")

                dir_map[file] = file_size

        # Validate file contents
        for file in os.listdir(path):
            file_path = os.path.join(path, file)
            if os.path.isfile(file_path) and file.lower() not in OCFL_OBJECT_HEADERS:
                expected_checksum = root_files[file.lower()]
                actual_checksum = None
                with open(file_path, "rb") as f:
                    actual_checksum = compute_sha512(f)

                if expected_checksum != actual_checksum:
                    raise ValueError(f"Checksum mismatch: {file} - expected: {expected_checksum}, actual: {actual_checksum}")

        # Validate file sizes and checksums
        file_mismatch = False
        for file, size in dir_map.items():
            file_path = os.path.join(path, file)
            if os.path.isfile(file_path) and file.lower() not in OCFL_OBJECT_HEADERS:
                file_size = os.path.getsize(file_path)
                if file_size != size:
                    file_mismatch = True

        if file_mismatch:
            raise ValueError("File size mismatch")

        return True

