def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("The 'fixity' argument must be a dictionary.")

    if not isinstance(manifest_files, list):
        raise ValueError("The 'manifest_files' argument must be a list.")

    # check that the fixity block has the required fields
    required_fields = ["files", "algorithms"]
    for field in required_fields:
        if field not in fixity:
            raise ValueError(f"The 'fixity' dictionary is missing the required field '{field}'.")

    # check that all files listed in the fixity block are in the manifest
    for file in fixity["files"]:
        if file not in manifest_files:
            raise ValueError(f"The fixity block references a file '{file}' that is not listed in the manifest.")

    # check that the algorithms listed in the fixity block are supported
    for algorithm in fixity["algorithms"]:
        if algorithm not in ["sha256", "md5"]:
            raise ValueError(f"The fixity block specifies an unsupported algorithm '{algorithm}'.")

    return True

def validate_fixity(self, fixity, manifest_files):
    if not fixity:
        raise ValueError("Fixity block is missing")
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block should be a dictionary")
    if not fixity.get("algorithm"):
        raise ValueError("Fixity algorithm is missing")
    if fixity.get("algorithm") not in ["MD5", "SHA1", "SHA256", "SHA512"]:
