def add_rendition(self, lang, file_path):
    lang = lang.strip().lower()
    if len(lang) != 2:
        raise ValueError("'lang' parameter must be a two-letter language code")

    file_path = Path(file_path).resolve()
    if not file_path.is_file():
        raise ValueError("'file_path' must be a path to a file")

    file_extension = file_path.suffix
    if file_extension == "":
        raise ValueError("'file_path' must have an extension")

    rendition_dict = getattr(self, lang, None)
    if rendition_dict is None:
        rendition_dict = {}

    if file_extension in rendition_dict:
        raise DuplicateKeyError(f"Rendition for language '{lang}' already exists")

    rendition_dict[file_extension] = file_path
    setattr(self, lang, rendition_dict)

