def pretty(self, indent=0, debug=False):
    indentation = '    ' * indent
    text = ''
    # obtain the relevant attributes of the current element
    attributes = self.attributes()
    # check if the element is a leaf element
    if len(attributes) == 0:
        text += indentation + self.tag + '\n'
    else:
        text += indentation + self.tag + '{\n'
        for attribute in attributes:
            text += indentation + attribute.pretty(indent + 1)
        text += indentation + '}'
    if debug: print(text)
    return text

def pretty(self, indent=0, debug=False):
    pretty_str = ""
    if indent != 0:
        pretty_str += "\n"
        pretty_str += indent * " "
    if debug:
        pretty_str += f"Debug info: self = {self}"
    else:
        pretty_str += str(self)
    return pretty_str

def pretty(self, indent=0, debug=False):
    result = ''
    if indent == 0 and not debug:
        result += self.__class__.__name__ + '(\n'
    else:
        result += '\t' * indent
        result += self.__class__.__name__ + '(\n'
    for attr, value in sorted(dir(self)):
        if not attr.startswith('__'):
            if isinstance(value, AbstractElement):
                continue
            if isinstance(value, list):
                if value:
                    result += '\t' * (indent + 1)
                    result += str(value[0]) + '\n'
                else:
                    result += '\t' * (indent + 1)
                    result += '[]\n'
            else:
                result += '\t' * (indent + 1)
                result += str(value) + '\n'
    if indent == 0 and not debug:
        result += ')'
    else:
        result += '\t' * indent
        result += ')'
    return result

