def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, "inventory.json")
        if not os.path.exists(inventory_path):
            raise FileNotFoundError(f"Inventory for version {version_dir} not found")
        inventory = json.load(inventory_path)
        if inventory is None:
            raise ValueError(f"Inventory for version {version_dir} is empty")
        if version_dir == "":
            # root version, check that the inventory matches the root manifest
            root_manifest = self.manifest
            for key, value in inventory.items():
                if key not in root_manifest:
                    raise KeyError(f"Inventory for version {version_dir} contains an object that is not in the root manifest")
                if root_manifest[key] != value:
                    raise ValueError(f"Inventory for version {version_dir} contains an invalid content digest for object {key}")
        else:
            # file version, find the parent version's inventory and update it
            parent_inventory = self.get_inventory(os.path.dirname(version_dir))
            if isinstance(parent_inventory, dict):
                parent_inventory.update(inventory)
            else:
                raise TypeError(f"Parent inventory for version {version_dir} is not a dict")
            self.set_inventory(os.path.dirname(version_dir), parent_inventory)
    return version_dirs

def validate_version_inventories(self, version_dirs):
    if not version_dirs: return
    if not isinstance(version_dirs, list): raise ValueError("version_dirs must be a list of strings")
    for i, d in enumerate(version_dirs):
        if not isinstance(d, str): raise ValueError(f"version_dirs must be a list of strings, not {type(d).__name__}")
        if not os.path.isdir(d): raise ValueError(f"No such directory: {d}")
        if not os.path.isfile(os.path.join(d, "inventory.json")): raise ValueError(f"No inventory.json found in directory {d}")
        if i > 0 and d < version_dirs[i-1]: raise ValueError(f"version_dirs must be in version sequence (1, 2, 3, ...), not '{d}' < '{version_dirs[i-1]}'")
        if i > 0 and os.path.getmtime(os.path.join(d, "inventory.json")) < os.path.getmtime(os.path.join(version_dirs[i-1], "inventory.json")):
            raise ValueError(f"Inventory file '{os.path.join(d, 'inventory.json')}' is older than '{os.path.join(version_dirs[i-1], 'inventory.json')}'")

