        # Check that the content hashes are valid.
        content_hashes = inventory_data['content-hashes']
        for content_type, hash in content_hashes.items():
            if not isinstance(hash, str):
                raise ValidationError(f"Invalid type of content hash for type {content_type} in inventory file for version {version_dir}")
            if not validate_hash(hash):
                raise ValidationError(f"Invalid content hash for type {content_type} in inventory file for version {version_dir}: {hash}")
        # Check that the content version corresponds to the version.
        content_version = inventory_data['content-version']
        if content_version != version_dir:
