def find_path_type(path):
    # Assumes path is a string
    if not isinstance(path, str):
        raise TypeError("path must be a string")

    # Check if path points to a directory
    if not os.path.isdir(path):
        raise NotADirectoryError(f"{path} is not a directory")

    # Check if path points to a valid OCFL object
    if os.path.join(path, "0=*") not in os.listdir(path):
        return "root"

    else:
        # Check if path points to a valid OCFL object,
        # not just a directory containing an OCFL object
        try:
            inventory_contents = ocfl.inventory(path)
        except ocfl.InventoryNotFoundError:
            return "object"

        if len(inventory_contents) == 0:
            return "file"

        return "Other: " + os.path.join(path, "0=*")

