def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size
    """
    size_mapping = {"B": 1, "K": 1e3, "M": 1e6, "G": 1e9, "T": 1e12}
    try:
        size = int(size[:-1]) * size_mapping[size[-1]]
    except (ValueError, KeyError):
        raise ValueError("Invalid input size string")
    return size

def size_to_bytes(size_string: str) -> int:
    size_string = size_string.upper()
    regex = "([0-9]+)(K|M|G|T)"
    match = re.match(regex,size_string)
    if match:
        value = int(match.group(1))
        unit = match.group(2)
        if unit == 'K':
            return value * 1000
        elif unit == 'M':
            return value * 1000000
        elif unit == 'G':
            return value * 1000000000
        elif unit == 'T':
            return value * 1000000000000
        else:
            raise ValueError("Invalid size string")
    else:
        raise ValueError("Invalid size string")

