def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform == 'this':
        if os.name == 'nt':
            platform = 0
        else:
            platform = 1

    if platform == 1:
        return re.split(r'''((?:^'[^']*'"|[^'\\]|\\.)*)''', s.strip())
    else:
        return re.split(r'''((?:"[^"\\]*"|[^"]|"|\\.)*)''', s.strip())

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """

    if platform == 'this':
        platform = '1' if 'posix' in os.name.lower() else '0'

    if platform == '1':
        return re.findall(r"[^ \t\n\v\f\r']+|'[^']*'", s)
    elif platform == '0':
        regex = re.compile(r'(?:^\\[\"\']?|[^\\]\\[\'\"])[^\"^\']*')
        return [match.replace('\\\\', '\\') for match in regex.findall(s)]
    else:
        raise ValueError("Unsupported platform: " + platform)

