def prepare_repository_from_archive(archive_path, filename=None, tmp_path="/tmp"):
        if not os.path.exists(archive_path):
            raise ValueError("The specified archive path does not exist")
        if not os.path.isfile(archive_path):
            raise ValueError("The specified archive is not a file")

        if filename is None:
            filename = os.path.basename(archive_path)
        if not filename.endswith(".tar.gz"):
            raise ValueError("Filename must have .tar.gz extension")

        if not os.path.isdir(tmp_path):
            raise ValueError("Temporary path is not a directory")

        tmp_dir = os.path.join(tmp_path, filename.replace(".tar.gz", ""))
        if os.path.exists(tmp_dir):
            raise ValueError("Temporary path already exists")

        # extract the archive to the temporary directory
        subprocess.run(["tar", "-xzf", archive_path, "-C", tmp_dir])

        return tmp_dir

def prepare_repository_from_archive(archive_path, filename=None, tmp_path='/tmp'):
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    try:
        archive_path = Path(archive_path)
        if not archive_path.exists():
            raise ValueError(f"File does not exist: {archive_path}")
        if filename:
            if not filename.endswith(".tar.gz"):
                raise ValueError(f"Filename must end with '.tar.gz': {filename}")
        else:
            filename = archive_path.stem + '.tar.gz'

        with TemporaryDirectory(dir=tmp_path) as tmp_dir:
            tmp_path = Path(tmp_dir)
            subprocess.check_call(["tar", "-xzf", archive_path, "-C", str(tmp_path)])
            return str(tmp_path.joinpath(filename))
    except (FileNotFoundError, RuntimeError) as err:
        raise ValueError(f"Unable to extract file: {err}")

prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Check input parameters
    if not isinstance(archive_path, str):
        raise ValueError("Invalid archive_path provided. Must be a string.")
    if filename is not None and not isinstance(filename, str):
        raise ValueError("Invalid filename provided. Must be a string or None.")
    if not isinstance(tmp_path, PosixPath) and not isinstance(tmp_path, str):
        raise ValueError("Invalid tmp_path provided. Must be a PosixPath or string.")

    # Call subprocess to uncompress the archive
    try:
        if filename is not None:
            subprocess.check_call(["tar", "-xf", archive_path, "-C", tmp_path, "--strip-components=1", filename])
        else:
            subprocess.check_call(["tar", "-xf", archive_path, "-C", tmp_path, "--strip-components=1"])
    except subprocess.CalledProcessError as e:
        raise ValueError("Error uncompressing archive file. Check the archive_path and make sure it exists.") from e

    # Return the file repo url
    return str(tmp_path) + "/" + (filename or os.path.basename(archive_path))

