def make_find_paths(find_paths):
    import re
    patterns = []
    for path in find_paths:
        if not path.startswith('sh:'):
            patterns.append('sh:**/*{0}*/**'.format(path))
        else:
            patterns.append(path)
    return patterns

def make_find_paths(find_paths):
    import re

    transformed_paths = []

    for path in find_paths:
        if ':' in path and path not in transformed_paths:
            # preserve existing glob pattern
            transformed_paths.append(path)
        else:
            # transform path fragment into glob pattern
            if path.startswith('~'):
                # strip leading tilda
                transformed_paths.append(path[1:])
            else:
                transformed_paths.append('sh:**/*' + path + '*/**')

    return transformed_paths

