def _verify(iface, candidate):
    """
    Verify that *candidate* might correctly provide *iface*.
    :param iface:
    :param candidate:
    :return bool:
    """
    provided = iface.providedBy(candidate)
    if not provided:
        raise zope.interface.Invalid("Interface {} is not provided by {}.".format(iface, candidate))

    empties = []
    for name, attr in iface.ObjectSpecification.attrs.items():
        try:
            value = getattr(candidate, name)
        except AttributeError:
            empties.append(name)
            continue
        if not isinstance(value, attr.type):
            raise zope.interface.Invalid("{} attribute {} of candidate {} must be of type {} but is of type {}.".format(candidate, name, attr.type.__name__, type(value).__name__))

    for name, method in iface.ObjectSpecification.methods.items():
        try:
            value = getattr(candidate, name)
        except AttributeError:
            empties.append(name)
            continue
        if not callable(value):
            raise zope.interface.Invalid("{} method {} of candidate {} must be callable but is not.".format(candidate, name, value))

    return not empties

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"{candidate} does not provide {iface}")

    for name, method in iface.methods.items():
        if not hasattr(candidate, name):
            raise Invalid(f"{candidate} does not have the method {name}")

        candidate_method = getattr(candidate, name)
        if not signature_valid(method, candidate_method):
            raise Invalid(f"Signature of {candidate}.{name} does not match the required signature")

    for name, attribute in iface.attributes.items():
        if not hasattr(candidate, name):
            raise Invalid(f"{candidate} does not have the attribute {name}")

        candidate_attribute = getattr(candidate, name)
        if not vtype or not vtype.matches(candidate_attribute):
            raise Invalid(f"Attribute {name} does not match required type")

    return True

