def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Validate the arguments
    if not isinstance(public_key, PublicKey):
        raise TypeError("public_key must be of type PublicKey")
    if not isinstance(doc, XmlDocument):
        raise TypeError("doc must be of type XmlDocument")
    if not isinstance(signature, Signature):
        raise TypeError("signature must be of type Signature")

    # Verify the signature
    if not public_key.verify(doc.get_payload(), signature):
        raise ValueError("Invalid signature: The claimed author did not generate this message")

    # Verify that the signature is not expired
    if signature.get_timestamp().timestamp() + EXPIRE_PERIOD < time():
        raise ValueError("Invalid signature: The signature is expired")

    return True

def verify_relayable_signature(public_key, doc, signature):
    # Verify the signed XML elements
    for element in doc.getroot():
        if element.get("signature"):
            if not element.verify(public_key):
                raise ValueError("Invalid signature for element: " + str(element))

    # Verify the signature for the complete document
    if not doc.verify(public_key, signature):
        raise ValueError("Invalid signature for the complete message")

