    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Check if the document is JSON
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass

    # Check if the document is XRD
    try:
        xrd = xri_lib.xrd.parseString(document)
        services = []
        for service in xrd.services.services:
            services.append(service)
        return services
    except xri_lib.xrd.XrdParseError:
        return None
    except xri_lib.xrd.stream_validator.XMLSchemaError:
        return None
    return None

