    root_block_type = data["root_block"]["type"]
    if root_block_type not in ALLOWED_ROOT_BLOCK_TYPES:
        raise IRValidatorException("Invalid root block type '" + root_block_type + "'")

    # check that optional_data is a dictionary
    if not isinstance(data["optional_data"], dict):
        raise IRValidatorException("optional_data must be a dictionary")

    return data

